// Mod My Claude - gallery. No dependencies, no build step.
// Reads ./mods.json (generated by scripts/build-catalog.mjs) and renders with DOM APIs only:
// every piece of data goes in through textContent or setAttribute, never innerHTML.
'use strict';

(() => {
  const CATEGORY_LABELS = {
    safety: 'Safety',
    cost: 'Cost and limits',
    visibility: 'See what Claude is doing',
    review: 'Review changes',
    insight: 'Catch what you would miss',
    memory: 'Memory',
    workflow: 'Workflow',
    alerts: 'Alerts',
    looks: 'Looks',
    fun: 'Fun',
    wellness: 'Wellness',
  };
  const CATEGORY_ORDER = Object.keys(CATEGORY_LABELS);
  const SURFACE_LABELS = { terminal: 'Terminal', desktop: 'Desktop app', vscode: 'VS Code' };
  const CALM_REACH = new Set(['display only']);
  const UNKNOWN_REACH = new Set(['unverified']);
  const NAME_RE = /^[a-z0-9][a-z0-9_-]*$/i;
  const MEDIA_FILE_RE = /^[a-z0-9][a-z0-9_.-]*\.(gif|png|webp|jpe?g|avif)$/i;
  const SVG_NS = 'http://www.w3.org/2000/svg';
  const reduceMotion = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  // Animated first, unless the viewer asked for less motion: then prefer a still.
  const MEDIA_EXTS = reduceMotion ? ['png', 'webp', 'gif'] : ['gif', 'png', 'webp'];

  const $ = id => document.getElementById(id);
  const els = {
    count: $('mod-count'),
    q: $('q'),
    chips: $('chips'),
    resultCount: $('result-count'),
    grid: $('grid'),
    empty: $('empty'),
    clear: $('clear'),
    starters: $('starters'),
    dialog: $('mod-dialog'),
    dlgPath: $('dlg-path'),
    dlgMain: $('dlg-main'),
    dlgClose: $('dlg-close'),
    dlgLive: $('dlg-live'),
    live: $('live'),
  };

  let org = 'modmyclaude';
  let repo = 'claude-code-mods';
  let mods = [];
  const byName = new Map();
  const cardOf = new Map();
  const state = { cat: 'all', q: '', mod: null };

  // ---------- tiny DOM helpers (text only) ----------

  function h(tag, attrs, ...kids) {
    const el = document.createElement(tag);
    setAttrs(el, attrs);
    el.append(...kids.flat().filter(k => k != null && k !== false));
    return el;
  }

  function s(tag, attrs, ...kids) {
    const el = document.createElementNS(SVG_NS, tag);
    setAttrs(el, attrs);
    el.append(...kids.filter(k => k != null));
    return el;
  }

  function setAttrs(el, attrs) {
    if (!attrs) return;
    for (const [k, v] of Object.entries(attrs)) {
      if (v == null || v === false) continue;
      if (k === 'text') el.textContent = String(v);
      else if (k.startsWith('on') && typeof v === 'function') el.addEventListener(k.slice(2), v);
      else el.setAttribute(k, v === true ? '' : String(v));
    }
  }

  const str = v => (typeof v === 'string' ? v : v == null ? '' : String(v));
  const list = v => (Array.isArray(v) ? v.map(str).filter(Boolean) : []);
  const capFirst = t => (t ? t.charAt(0).toUpperCase() + t.slice(1) : t);
  const catLabel = c => CATEGORY_LABELS[c] || capFirst(str(c).replace(/[-_]+/g, ' '));

  // ---------- data-derived strings ----------

  const installLine = name => `/plugin install ${name} --marketplace ${org}/${repo}`;
  const addMarketplaceLine = () => `/plugin marketplace add ${org}/${repo}`;
  const shortInstallLine = name => `/plugin install ${name}@${org}`;
  const codeUrl = name => `https://github.com/${encodeURIComponent(org)}/${encodeURIComponent(repo)}/tree/main/mods/${encodeURIComponent(name)}`;
  const modHref = name => `#mod=${encodeURIComponent(name)}`;

  function surfacesText(surfaces) {
    const names = surfaces.map(x => SURFACE_LABELS[x] || capFirst(x));
    if (!names.length) return 'Not stated';
    return names.length === 1 ? `${names[0]} only` : names.join(' + ');
  }

  function normalise(raw) {
    const name = str(raw.name).trim();
    return {
      name,
      title: str(raw.title) || name,
      tagline: str(raw.tagline),
      category: str(raw.category),
      surfaces: list(raw.surfaces),
      modelCalls: str(raw.modelCalls) || 'none',
      version: str(raw.version),
      keywords: list(raw.keywords),
      prompt: str(raw.prompt),
      reach: list(raw.reach),
      media: raw.media, // optional: a filename in media/, or null for "no media"; absent means probe
    };
  }

  // ---------- copy to clipboard with visible + announced feedback ----------

  const timers = new WeakMap();

  async function copyText(text) {
    try {
      if (navigator.clipboard && window.isSecureContext) {
        await navigator.clipboard.writeText(text);
        return true;
      }
    } catch (_) { /* fall through to the legacy path */ }
    const host = els.dialog.open ? els.dialog : document.body; // outside a modal dialog is inert
    const ta = h('textarea', { readonly: true, 'aria-hidden': 'true', tabindex: '-1', class: 'vh' });
    ta.value = text;
    host.append(ta);
    const prev = document.activeElement;
    ta.select();
    let ok = false;
    try { ok = document.execCommand('copy'); } catch (_) { ok = false; }
    ta.remove();
    if (prev && prev.focus) prev.focus();
    return ok;
  }

  function announce(msg) {
    const region = els.dialog.open ? els.dlgLive : els.live;
    region.textContent = '';
    setTimeout(() => { region.textContent = msg; }, 60);
  }

  async function copyFrom(btn, text, what) {
    const ok = await copyText(text);
    const lbl = btn.querySelector('.lbl') || btn;
    if (!btn.dataset.idle) btn.dataset.idle = lbl.textContent;
    lbl.textContent = ok ? 'Copied' : 'Copy failed';
    btn.classList.toggle('is-copied', ok);
    btn.classList.toggle('is-failed', !ok);
    announce(ok ? `Copied ${what}.` : `Could not copy ${what}. Select the text and copy it yourself.`);
    clearTimeout(timers.get(btn));
    timers.set(btn, setTimeout(() => {
      lbl.textContent = btn.dataset.idle;
      btn.classList.remove('is-copied', 'is-failed');
    }, 2200));
  }

  // A copy button: visible label, plus hidden context so ten "Copy prompt" buttons are told apart.
  function copyButton(label, context, getText, what, extraClass) {
    const btn = h('button', { type: 'button', class: `btn${extraClass ? ' ' + extraClass : ''}` },
      h('span', { class: 'lbl', text: label }),
      context ? h('span', { class: 'vh', text: ` ${context}` }) : null);
    btn.addEventListener('click', () => copyFrom(btn, getText(), what));
    return btn;
  }

  function cmdBox(text, label, what, marker) {
    return h('div', { class: 'cmd' },
      h('span', { class: marker === '>' ? 'cmd-prompt' : 'cmd-step', 'aria-hidden': 'true', text: marker }),
      h('code', { text }),
      copyButton('Copy', label, () => text, what));
  }

  // ---------- reach badges ----------

  function badges(reach) {
    const items = reach.length ? reach : ['unverified'];
    return h('ul', { class: 'badges', role: 'list' }, items.map(r => {
      const tone = CALM_REACH.has(r) ? ' is-calm' : UNKNOWN_REACH.has(r) ? ' is-unknown' : '';
      return h('li', {
        class: `badge${tone}`,
        title: UNKNOWN_REACH.has(r) ? 'The validator could not report on this mod. Read its code before installing.' : null,
        text: r,
      });
    }));
  }

  function spec(m, { showNone } = {}) {
    const rows = [['Runs in', surfacesText(m.surfaces)]];
    const calls = m.modelCalls.trim();
    if (calls.toLowerCase() !== 'none') rows.push(['Model calls', capFirst(calls)]);
    else if (showNone) rows.push(['Model calls', 'None']);
    if (showNone && m.version) rows.push(['Version', m.version]);
    rows.push(['Can reach', badges(m.reach)]);
    return h('dl', { class: 'spec' }, rows.map(([k, v]) => h('div', { style: 'display:contents' },
      h('dt', { text: k }), h('dd', null, v))));
  }

  // ---------- generated placeholder (deterministic per mod name) ----------

  function hash32(text) {
    let x = 0x811c9dc5;
    for (const ch of text) { x ^= ch.codePointAt(0); x = Math.imul(x, 0x01000193); }
    return x >>> 0;
  }

  function placeholder(m) {
    let seed = hash32(m.name || m.title) || 1;
    const rnd = () => { seed ^= seed << 13; seed >>>= 0; seed ^= seed >>> 17; seed ^= seed << 5; seed >>>= 0; return seed / 4294967296; };
    const W = 320, H = 200, C = 22, N = 5;
    const gx = (W - N * C) / 2, gy = (H - N * C) / 2 - 8;

    // A 5x5 glyph, mirrored left to right, like a part stamp.
    const on = new Set();
    for (let y = 0; y < N; y++) for (let x = 0; x < 3; x++) if (rnd() < 0.52) { on.add(`${x},${y}`); on.add(`${N - 1 - x},${y}`); }
    for (let y = 1; y < 4 && on.size < 9; y++) on.add(`2,${y}`);
    const half = [...on].filter(k => Number(k.split(',')[0]) <= 2);
    const pick = half[Math.floor(rnd() * half.length)];
    const [px, py] = pick.split(',').map(Number);
    const hot = new Set([`${px},${py}`, `${N - 1 - px},${py}`]);

    let d = '';
    for (let x = 20; x < W; x += 20) d += `M${x} 0V${H}`;
    for (let y = 20; y < H; y += 20) d += `M0 ${y}H${W}`;

    const cells = [...on].map(k => {
      const [x, y] = k.split(',').map(Number);
      return s('rect', { class: hot.has(k) ? 'ph-hot' : 'ph-on', x: gx + x * C + 1, y: gy + y * C + 1, width: C - 2, height: C - 2 });
    });
    const corner = (x, y, dx, dy) => s('path', { class: 'ph-mark', d: `M${x} ${y + 12 * dy}V${y}H${x + 12 * dx}` });

    return s('svg', { viewBox: `0 0 ${W} ${H}`, 'aria-hidden': 'true', focusable: 'false' },
      s('rect', { class: 'ph-bg', width: W, height: H }),
      s('path', { class: 'ph-grid', d }),
      corner(12, 12, 1, 1), corner(W - 12, 12, -1, 1), corner(12, H - 12, 1, -1), corner(W - 12, H - 12, -1, -1),
      ...cells,
      s('text', { class: 'ph-label', x: 24, y: H - 20 }, document.createTextNode(`mods/${m.name}`)),
      m.version ? s('text', { class: 'ph-label', x: W - 24, y: H - 20, 'text-anchor': 'end' }, document.createTextNode(`v${m.version}`)) : null);
  }

  // ---------- media: media/<name>.gif, else .png, else .webp; lazy, never a broken image ----------

  const slotMod = new WeakMap();

  function mediaCandidates(m) {
    if (m.media === null) return [];
    if (typeof m.media === 'string') return MEDIA_FILE_RE.test(m.media) ? [m.media] : [];
    return NAME_RE.test(m.name) ? MEDIA_EXTS.map(ext => `${m.name}.${ext}`) : [];
  }

  function loadMedia(slot) {
    const m = slotMod.get(slot);
    if (!m) return;
    const queue = mediaCandidates(m);
    const next = () => {
      const file = queue.shift();
      if (!file) return; // keep the placeholder
      const img = new Image();
      img.decoding = 'async';
      img.alt = `${m.title} running in Claude Code`;
      img.onload = () => slot.replaceChildren(img);
      img.onerror = next;
      img.src = `media/${encodeURIComponent(file)}`;
    };
    next();
  }

  const io = 'IntersectionObserver' in window
    ? new IntersectionObserver(entries => {
      for (const e of entries) if (e.isIntersecting) { io.unobserve(e.target); loadMedia(e.target); }
    }, { rootMargin: '400px 0px' })
    : null;

  // ---------- cards ----------

  function card(m) {
    const titleId = `t-${m.name}`;
    const media = h('div', { class: 'media' }, placeholder(m));
    slotMod.set(media, m);

    const link = h('a', { class: 'card-link', href: modHref(m.name), text: m.title });
    link.addEventListener('click', e => {
      if (e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
      e.preventDefault();
      openMod(m.name);
    });

    const li = h('li', { class: 'card', 'data-cat': m.category },
      media,
      h('div', { class: 'card-body' },
        h('p', { class: 'eyebrow', text: catLabel(m.category) }),
        h('h3', { id: titleId }, link),
        m.tagline ? h('p', { class: 'tagline', text: m.tagline }) : null,
        spec(m),
        h('div', { class: 'actions' },
          copyButton('Copy install', `for ${m.title}`, () => installLine(m.name), `the install line for ${m.title}`, 'btn-solid'),
          m.prompt ? copyButton('Copy prompt', `for ${m.title}`, () => m.prompt, `the prompt for ${m.title}`) : null,
          h('a', { class: 'btn', href: codeUrl(m.name) },
            'View code', h('span', { class: 'vh', text: ` for ${m.title} on GitHub` })))));

    if (io) io.observe(media); else loadMedia(media);
    return li;
  }

  // ---------- filtering + URL hash state ----------

  function matches(m) {
    if (state.cat !== 'all' && m.category !== state.cat) return false;
    const terms = state.q.toLowerCase().split(/\s+/).filter(Boolean);
    if (!terms.length) return true;
    const hay = [m.title, m.name, m.tagline, ...m.keywords].join(' ').toLowerCase();
    return terms.every(t => hay.includes(t));
  }

  function render() {
    let shown = 0;
    for (const m of mods) {
      const ok = matches(m);
      cardOf.get(m.name).hidden = !ok;
      if (ok) shown++;
    }
    for (const chip of els.chips.children) chip.setAttribute('aria-pressed', String(chip.dataset.cat === state.cat));
    els.empty.hidden = shown > 0;
    const total = mods.length;
    const filtered = state.cat !== 'all' || state.q.trim();
    els.resultCount.textContent = !filtered
      ? `All ${total} mods`
      : `${shown} of ${total} mods${state.cat !== 'all' ? ` in ${catLabel(state.cat)}` : ''}${state.q.trim() ? ` matching "${state.q.trim()}"` : ''}`;
  }

  function readHash() {
    const raw = location.hash.slice(1);
    if (!raw.includes('=')) return null; // a plain section anchor like #safety: leave state alone
    const p = new URLSearchParams(raw);
    return { cat: p.get('cat') || 'all', q: (p.get('q') || '').slice(0, 80), mod: p.get('mod') };
  }

  function writeHash() {
    const p = new URLSearchParams();
    if (state.cat !== 'all') p.set('cat', state.cat);
    if (state.q.trim()) p.set('q', state.q.trim());
    if (state.mod) p.set('mod', state.mod);
    const next = p.toString();
    if (next) {
      if (location.hash !== `#${next}`) history.replaceState(null, '', `#${next}`);
    } else if (location.hash) {
      history.replaceState(null, '', location.pathname + location.search);
    }
  }

  function applyHash() {
    const next = readHash();
    if (!next) return false;
    const cats = new Set(mods.map(m => m.category));
    state.cat = cats.has(next.cat) ? next.cat : 'all';
    state.q = next.q;
    if (els.q.value !== state.q) els.q.value = state.q;
    render();
    if (next.mod && byName.has(next.mod)) openMod(next.mod);
    else {
      if (els.dialog.open) els.dialog.close();
      if (next.mod) { state.mod = null; writeHash(); }
    }
    return true;
  }

  function setFilter(cat, q) {
    state.cat = cat;
    state.q = q;
    render();
    writeHash();
  }

  function buildChips() {
    const counts = new Map();
    for (const m of mods) counts.set(m.category, (counts.get(m.category) || 0) + 1);
    const cats = [...counts.keys()].sort((a, b) => rank(a) - rank(b) || a.localeCompare(b));
    const chip = (cat, label, n) => {
      const b = h('button', { type: 'button', class: 'chip', 'data-cat': cat, 'aria-pressed': 'false' },
        label, h('span', { class: 'chip-n', text: n }), h('span', { class: 'vh', text: n === 1 ? ' mod' : ' mods' }));
      b.addEventListener('click', () => setFilter(cat, state.q));
      return b;
    };
    els.chips.replaceChildren(chip('all', 'All', mods.length), ...cats.map(c => chip(c, catLabel(c), counts.get(c))));
  }

  const rank = cat => { const i = CATEGORY_ORDER.indexOf(cat); return i < 0 ? CATEGORY_ORDER.length : i; };

  // ---------- detail dialog ----------

  let opener = null;

  function openMod(name) {
    const m = byName.get(name);
    if (!m) return;
    state.mod = name;
    els.dlgPath.textContent = `mods/${m.name}${m.version ? `  v${m.version}` : ''}`;

    const steps = h('ol', { class: 'steps' },
      h('li', null, cmdBox(addMarketplaceLine(), 'step 1, add the marketplace', 'step 1', '1')),
      h('li', null, cmdBox(shortInstallLine(m.name), 'step 2, install the mod', 'step 2', '2')));

    els.dlgMain.replaceChildren(
      h('p', { class: 'eyebrow', text: catLabel(m.category) }),
      h('h2', { id: 'dlg-title', text: m.title }),
      m.tagline ? h('p', { class: 'dlg-tagline', text: m.tagline }) : null,
      spec(m, { showNone: true }),

      h('div', { class: 'dlg-block' },
        h('h3', { text: 'Install' }),
        cmdBox(installLine(m.name), 'the install line', `the install line for ${m.title}`, '>'),
        h('p', { class: 'note', text: 'On an older Claude Code, or if that line does not work, run these two instead:' }),
        steps),

      m.prompt ? h('div', { class: 'dlg-block' },
        h('div', { class: 'dlg-head-row' },
          h('h3', { text: 'The prompt that built it' }),
          copyButton('Copy prompt', null, () => m.prompt, `the prompt for ${m.title}`, 'btn-solid')),
        h('p', { class: 'note', text: 'Paste it into Claude Code to build your own version. Change any line first if you want something different.' }),
        h('pre', { class: 'prompt', tabindex: '0', 'aria-label': `Prompt for ${m.title}` }, h('code', { text: m.prompt }))) : null,

      h('div', { class: 'dlg-foot' },
        h('a', { class: 'btn', href: codeUrl(m.name) }, 'View code on GitHub')));

    if (!els.dialog.open) {
      opener = document.activeElement;
      els.dialog.showModal();
    }
    els.dialog.scrollTop = 0;
    writeHash();
  }

  els.dialog.addEventListener('close', () => {
    state.mod = null;
    writeHash();
    if (opener && document.contains(opener) && opener.focus) opener.focus();
    opener = null;
  });
  els.dlgClose.addEventListener('click', () => els.dialog.close());
  els.dialog.addEventListener('click', e => {
    if (e.target !== els.dialog) return;
    const r = els.dialog.getBoundingClientRect();
    const inside = e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom;
    if (!inside) els.dialog.close();
  });

  // ---------- starters ----------

  function starter(st) {
    const title = str(st.title) || str(st.name);
    const prompt = str(st.prompt);
    return h('li', { class: 'starter' },
      h('h3', { text: title }),
      st.tagline ? h('p', { text: str(st.tagline) }) : null,
      prompt ? h('div', null, copyButton('Copy prompt', `for ${title}`, () => prompt, `the ${title} prompt`, 'btn-solid')) : null,
      prompt ? h('details', null,
        h('summary', { text: 'Read the prompt' }),
        h('pre', { class: 'prompt', tabindex: '0', 'aria-label': `${title} prompt` }, h('code', { text: prompt }))) : null);
  }

  // ---------- static hooks in the page ----------

  for (const btn of document.querySelectorAll('[data-copy-from]')) {
    btn.addEventListener('click', () => {
      const src = $(btn.dataset.copyFrom);
      if (src) copyFrom(btn, src.textContent.trim(), btn.dataset.copyWhat || 'the text');
    });
  }

  els.q.addEventListener('input', () => setFilter(state.cat, els.q.value));
  els.clear.addEventListener('click', () => { els.q.value = ''; setFilter('all', ''); els.q.focus(); });
  window.addEventListener('hashchange', applyHash);

  // ---------- boot ----------

  fetch('./mods.json')
    .then(r => { if (!r.ok) throw new Error(`mods.json: HTTP ${r.status}`); return r.json(); })
    .then(data => {
      if (data && typeof data.org === 'string' && NAME_RE.test(data.org)) org = data.org;
      if (data && typeof data.repo === 'string' && NAME_RE.test(data.repo)) repo = data.repo;
      mods = (Array.isArray(data && data.mods) ? data.mods : [])
        .map(normalise)
        .filter(m => NAME_RE.test(m.name) && !byName.has(m.name) && byName.set(m.name, m))
        .sort((a, b) => rank(a.category) - rank(b.category) || a.title.localeCompare(b.title));

      els.count.textContent = `${mods.length} ${mods.length === 1 ? 'mod' : 'mods'}`;
      for (const m of mods) cardOf.set(m.name, card(m));
      els.grid.replaceChildren(...cardOf.values());
      buildChips();

      const starters = Array.isArray(data && data.starters) ? data.starters : [];
      els.starters.replaceChildren(...starters.map(starter));

      if (!applyHash()) {
        render();
        const anchor = location.hash.slice(1);
        const target = anchor && document.getElementById(decodeURIComponent(anchor));
        if (target) { // content above it just grew: jump back to it without a smooth-scroll ride
          const root = document.documentElement;
          root.style.scrollBehavior = 'auto';
          target.scrollIntoView();
          root.style.scrollBehavior = '';
        }
      }
    })
    .catch(err => {
      console.error(err);
      els.resultCount.textContent = '';
      els.grid.replaceChildren(h('li', { class: 'empty load-error' },
        h('p', { text: 'The catalogue did not load.' }),
        h('a', { href: `https://github.com/${org}/${repo}#the-mods` }, 'See the mods on GitHub')));
    });
})();
